","allowMultiple":false},{"oldString":"  async function saveProject() {
    const project = { name: state.name, bpm: state.bpm, musical_key: state.key, tracks: state.tracks, settings: { duration: state.duration, instrumental: state.instrumental, volume: state.volume, prompt: state.prompt } };
