    } catch (error) { showToast(error.message); }
  }
","newString":"  async function saveProject() {
    const project = { name: state.name, bpm: state.bpm, musical_key: state.key, tracks: state.tracks, settings: { duration: state.duration, instrumental: state.instrumental, volume: state.volume, prompt: state.prompt } };
    try {
      const saved = state.projectId
        ? await api(`projects/${state.projectId}/`, { method: "PATCH", body: JSON.stringify(project) })
        : await api("projects/", { method: "POST", body: JSON.stringify(project) });
      state.projectId = saved.id;
      localStorage.setItem(storageKey, JSON.stringify(state));
      upsertProject(saved);
    } catch (error) { showToast(error.message); }
  }
  function renderProjects() {
    const list = $("#project-list");
    list.innerHTML = "";
    const visibleProjects = authenticated ? projects : [{ id: "local", name: state.name }];
    visibleProjects.forEach(project => {
      const row = document.createElement("button");
      row.className = `project-row${project.id === state.projectId || (!authenticated && project.id === "local") ? " selected" : ""}`;
      row.dataset.projectId = project.id;
      const dot = document.createElement("span"); dot.className = "project-dot";
      const label = document.createElement("span"); label.textContent = project.name;
      row.append(dot, label);
      row.addEventListener("click", () => project.id === "local" ? showToast("This guest session is saved in this browser.") : openProject(project.id));
      list.append(row);
    });
  }
  function upsertProject(project) {
    const index = projects.findIndex(item => item.id === project.id);
    if (index < 0) projects.unshift(project); else projects[index] = project;
    renderProjects();
  }
  async function loadProjects() {
    try {
      projects = await api("projects/");
      renderProjects();
    } catch (error) { showToast(error.message); }
  }
  async function openProject(id) {
    try {
      const project = await api(`projects/${id}/`);
      state = { ...blankState(), projectId: project.id, name: project.name, bpm: project.bpm, key: project.musical_key, tracks: project.tracks, ...(project.settings || {}) };
      hydrate();
      localStorage.setItem(storageKey, JSON.stringify(state));
      renderProjects();
    } catch (error) { showToast(error.message); }
  }
","allowMultiple":false}]}}

